import{_ as i,c as t,o,a3 as n}from"./chunks/framework.CoV49S2T.js";const g=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/introduction.md","filePath":"fr/guide/introduction.md","lastUpdated":1787284674000}'),a={name:"fr/guide/introduction.md"};function r(s,e,l,u,c,p){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><h2 id="a-propos-de-clipboxai" tabindex="-1">À propos de ClipboxAI <a class="header-anchor" href="#a-propos-de-clipboxai" aria-label="Permalink to &quot;À propos de ClipboxAI&quot;">​</a></h2><p><strong>ClipboxAI</strong> est un gestionnaire de presse-papiers intelligent pour macOS. À chaque fois que vous copiez du texte, du code ou un lien, il est enregistré dans un historique consultable depuis votre barre de menus. En un clic — ou de façon totalement automatique — vous pouvez exécuter une action sur cet élément : le résumer, le traduire, le mettre en forme, ou le confier à un modèle d&#39;IA cloud.</p><p>Il repose sur deux types d&#39;outils :</p><ul><li><strong>Outils locaux intégrés</strong> qui s&#39;exécutent entièrement sur votre Mac, sans connexion réseau.</li><li><strong>Actions IA</strong> qui appellent un modèle cloud que vous configurez vous-même (votre propre clé API, stockée dans le Keychain du système).</li></ul><h2 id="fonctionnalites-cles" tabindex="-1">Fonctionnalités clés <a class="header-anchor" href="#fonctionnalites-cles" aria-label="Permalink to &quot;Fonctionnalités clés&quot;">​</a></h2><h3 id="📋-historique-du-presse-papiers" tabindex="-1">📋 Historique du presse-papiers <a class="header-anchor" href="#📋-historique-du-presse-papiers" aria-label="Permalink to &quot;📋 Historique du presse-papiers&quot;">​</a></h3><p>Tout ce que vous copiez est capturé automatiquement et conservé dans un historique consultable. Revenez à n&#39;importe quel élément précédent depuis la barre de menus — plus aucun extrait perdu.</p><h3 id="⚡-suggestions-intelligentes" tabindex="-1">⚡ Suggestions intelligentes <a class="header-anchor" href="#⚡-suggestions-intelligentes" aria-label="Permalink to &quot;⚡ Suggestions intelligentes&quot;">​</a></h3><p>ClipboxAI propose les actions les plus pertinentes pour l&#39;élément en cours. Acceptez une suggestion, ou parcourez la liste complète des outils.</p><h3 id="🛠️-outils-locaux-integres" tabindex="-1">🛠️ Outils locaux intégrés <a class="header-anchor" href="#🛠️-outils-locaux-integres" aria-label="Permalink to &quot;🛠️ Outils locaux intégrés&quot;">​</a></h3><p>Hors ligne, privé, instantané :</p><ul><li><strong>Extraire les liens</strong> — extrait toutes les URL d&#39;un bloc de texte.</li><li><strong>Compter les statistiques</strong> — nombre de mots, de caractères, de lignes et de phrases.</li><li><strong>Réduire les lignes vides</strong> — nettoie le texte collé en une seule étape.</li></ul><p>D&#39;autres outils locaux pourront être ajoutés avec le temps — ils ne quittent jamais votre appareil.</p><h3 id="✨-actions-ia" tabindex="-1">✨ Actions IA <a class="header-anchor" href="#✨-actions-ia" aria-label="Permalink to &quot;✨ Actions IA&quot;">​</a></h3><p>Envoyez l&#39;élément en cours à un modèle cloud pour :</p><ul><li><strong>Résumer</strong> de longs articles et fils de discussion.</li><li><strong>Traduire</strong> entre différentes langues.</li><li><strong>Réécrire / corriger</strong> le ton et la clarté.</li><li>Exécuter n&#39;importe quelle action depuis le <strong>Marketplace</strong>.</li></ul><h3 id="🛒-marketplace-d-actions" tabindex="-1">🛒 Marketplace d&#39;actions <a class="header-anchor" href="#🛒-marketplace-d-actions" aria-label="Permalink to &quot;🛒 Marketplace d&#39;actions&quot;">​</a></h3><p>Parcourez les actions IA créées par la communauté et installez-les en un clic via un lien profond (<code>clipboxai://install?action=&lt;id&gt;</code>). Les catégories comprennent Écriture, Développeur, Productivité, Traduction, Réseaux sociaux et Analyse.</p><h3 id="🔒-prive-par-conception" tabindex="-1">🔒 Privé par conception <a class="header-anchor" href="#🔒-prive-par-conception" aria-label="Permalink to &quot;🔒 Privé par conception&quot;">​</a></h3><p>Votre historique de presse-papiers reste sur votre appareil. L&#39;IA cloud est <strong>optionnelle</strong> : lorsqu&#39;elle est activée, le contenu n&#39;est envoyé qu&#39;au fournisseur <em>que vous</em> choisissez, à l&#39;aide d&#39;une clé API stockée dans votre Keychain. Nous ne recevons ni ne stockons vos éléments, et il n&#39;y a aucune analytique ni télémétrie.</p><h2 id="configuration-requise" tabindex="-1">Configuration requise <a class="header-anchor" href="#configuration-requise" aria-label="Permalink to &quot;Configuration requise&quot;">​</a></h2><ul><li><strong>Système d&#39;exploitation</strong> : macOS 14 Sonoma ou version ultérieure</li><li><strong>Processeur</strong> : Apple Silicon (série M) ou Intel (64 bits)</li><li><strong>Mémoire</strong> : 4 Go de RAM minimum, 8 Go recommandés</li><li><strong>Stockage</strong> : ~50 Mo pour l&#39;installation</li><li><strong>Pour l&#39;IA cloud</strong> : une clé API d&#39;un fournisseur pris en charge (DeepSeek, MiniMax, Zhipu GLM, Kimi, Mistral, Ollama, OpenAI, Anthropic ou Gemini)</li></ul><h2 id="langues-prises-en-charge" tabindex="-1">Langues prises en charge <a class="header-anchor" href="#langues-prises-en-charge" aria-label="Permalink to &quot;Langues prises en charge&quot;">​</a></h2><p>L&#39;application et ce site prennent en charge 7 langues : anglais, chinois simplifié (简体中文), chinois traditionnel (繁體中文), japonais (日本語), allemand, espagnol, français.</p><h2 id="pour-commencer" tabindex="-1">Pour commencer <a class="header-anchor" href="#pour-commencer" aria-label="Permalink to &quot;Pour commencer&quot;">​</a></h2><p>Si vous découvrez ClipboxAI, commencez par le <a href="/fr/guide/installation.html">Guide d&#39;installation</a> pour faire fonctionner l&#39;application sur votre Mac, puis lisez <a href="/fr/guide/usage.html">Utilisation</a> pour comprendre le fonctionnement des actions.</p>',27)])])}const m=i(a,[["render",r]]);export{g as __pageData,m as default};
